from scipy.optimize import least_squares
def m4(q,t,P,a,b):
    return q[0]*P**2 + q[1]*np.log(1+q[2]*P)*t + q[3]*np.tanh(q[4]*t) + q[5]*t**a*P**b
var=np.sum((dP_dt-dP_dt.mean())**2)
results=[]
np.random.seed(2)
for a in [-2,-1,-0.5,0,0.5,1,1.5,2,3]:
  for b in [0,0.5,1,1.5,2,3,4]:
    best=None
    for s in range(6):
        x0=np.r_[np.abs(np.random.randn(3))*2, np.random.randn(2)]
        x0[2]=abs(x0[2])+0.1
        try:
            r=least_squares(lambda q: m4(q,t,P,a,b)-dP_dt, x0)
            if np.isfinite(r.cost) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    if best is not None: results.append((2*best.cost/var,a,b,np.round(best.x,3)))
for r_ in sorted(results,key=lambda z:z[0])[:8]: print(r_)

